
#[test]fn actual_resident_decoder_frame_restores_original_receipt_after_source_post_unwind(){
 use semio_framework_value_native_decoding::NativeDecodeFrame;
 let mut bank=Bank::new(true);let mut observer=|_|true;let native=NativeDecodeControl::new(1<<20,&mut observer);let receipt=match native.pause(){Ok(receipt)=>receipt,Err(_)=>panic!("empty original decoder admission must pause")};let identity=receipt.ledger_identity();let mut resident=NativeDecodeFrame::from_continuation(receipt);let mut frame=NativeReceivingEffect::default();let mut producer=OriginalEffectAuthority::new(Commands::<SealedMode>{source:bank.source.clone(),mode:PhantomData});let mut slots=Slots::<SealedMode>::default();let mut input=Some(73);let d=Slots::<SealedMode>::capture_demand().unwrap();let work=slots.capture_work_demand(&input).unwrap();
 resident.decode(&mut observer,|native|{complete(command(&mut bank,native,&mut frame,&mut producer,d,work,Command::Capture(&mut slots,&mut input))).result.unwrap();Ok::<_,ValueError>(())}).unwrap_or_else(|_|panic!("original capture failed"));
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||resident.decode(&mut observer,|native|bank.run(native,|native|SealedMode::advance(&mut slots,native)))));assert!(interrupted.is_err());assert_eq!(resident.ledger_identity(),identity);assert!(resident.has_pending_work());assert!(slots.advance_pending());let work_after=resident.actual_work();let spent_after=bank.wallet.lock().unwrap().spent.retained_capacity_bytes;
 for _ in 0..8{if slots.output_ready(){break}let turn=resident.decode(&mut observer,|native|bank.run(native,|native|SealedMode::advance(&mut slots,native))).unwrap_or_else(|_|panic!("same original pending frame must resume"));complete(turn).result.unwrap();}
 assert!(slots.output_ready());assert!(!resident.has_pending_work());assert_eq!(resident.ledger_identity(),identity);assert!(resident.actual_work()>=work_after);assert_eq!(bank.wallet.lock().unwrap().spent.retained_capacity_bytes,spent_after);let mut output=None;let d=SealedMode::take_demand(&slots).unwrap();resident.decode(&mut observer,|native|{complete(command(&mut bank,native,&mut frame,&mut producer,d,1,Command::Take(&mut slots,&mut output))).result.unwrap();Ok::<_,ValueError>(())}).unwrap_or_else(|_|panic!("original output must return"));
 for _ in 0..4{if slots.terminal_is_empty(){break}let d=slots.close_demand(4096).unwrap();let work=slots.close_work_demand(4096).unwrap();resident.decode(&mut observer,|native|{complete(command(&mut bank,native,&mut frame,&mut producer,d,work,Command::Close(&mut slots))).result.unwrap();Ok::<_,ValueError>(())}).unwrap_or_else(|_|panic!("original producer must close"));}
 assert!(slots.terminal_is_empty());let(mut owner,mut value)=(None,None);for _ in 0..8{if output.is_none()&&owner.is_none(){break}let(d,work)=SealedMode::consume_demand(&output,&owner).unwrap();resident.decode(&mut observer,|native|{complete(command(&mut bank,native,&mut frame,&mut producer,d,work,Command::Consume(&mut output,&mut owner,&mut value))).result.unwrap();Ok::<_,ValueError>(())}).unwrap_or_else(|_|panic!("original output must retire"));}
 assert_eq!(value,Some(73));assert_eq!(256-bank.wallet.lock().unwrap().fuel,resident.actual_work());assert!(producer.into_producer().is_ok());
}
